#include <zephyr/ztest.h>
#include <zephyr/onoff.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/atomic.h>

#define TIMEOUT_MS K_MSEC(100)

static K_SEM_DEFINE(onoff_sem, 0, 1);
static atomic_t current_state;

static int dummy_start(struct onoff_client *cli)
{
    ARG_UNUSED(cli);
    return 0;
}

static int dummy_stop(struct onoff_client *cli)
{
    ARG_UNUSED(cli);
    return 0;
}

static const struct onoff_client_api dummy_api = {
    .start = dummy_start,
    .stop = dummy_stop,
};

static struct onoff_client dummy_client = {
    .api = &dummy_api,
};

static struct onoff_manager mgr;

static void notify_cb(struct onoff_manager *mgr_ptr,
                      enum onoff_state state,
                      int rc)
{
    ARG_UNUSED(mgr_ptr);
    ARG_UNUSED(rc);

    atomic_set(&current_state, state);
    k_sem_give(&onoff_sem);
}

static void settle(enum onoff_state expected_state)
{
    int rc;
    rc = k_sem_take(&onoff_sem, TIMEOUT_MS);
    zassert_equal(rc, 0, "Failed to settle to expected state");
    zassert_equal(atomic_get(&current_state), expected_state,
                  "Unexpected state after settle");
}

static void onoff_api_test_basic_async(void)
{
    int rc;

    /* Start the manager asynchronously */
    rc = onoff_manager_start(&mgr, &notify_cb);
    zassert_equal(rc, 0, "Failed to start manager");
    settle(ONOFF_STATE_ON);

    /* Stop the manager asynchronously */
    rc = onoff_manager_stop(&mgr, &notify_cb);
    zassert_equal(rc, 0, "Failed to stop manager");
    settle(ONOFF_STATE_OFF);
}

static void onoff_api_test_basic_reset(void)
{
    int rc;

    /* Start the manager */
    rc = onoff_manager_start(&mgr, &notify_cb);
    zassert_equal(rc, 0, "Failed to start manager");
    settle(ONOFF_STATE_ON);

    /* Stop the manager */
    rc = onoff_manager_stop(&mgr, &notify_cb);
    zassert_equal(rc, 0, "Failed to stop manager");
    /* FIX: Ensure the manager is fully in ONOFF_STATE_OFF before calling reset. */
    settle(ONOFF_STATE_OFF);

    /* Reset the manager */
    rc = onoff_manager_reset(&mgr);
    zassert_not_equal(rc, ONOFF_STATE_ERROR, "Reset failed unexpectedly");
    zassert_equal(atomic_get(&current_state), ONOFF_STATE_OFF, "Manager not in OFF state after reset");
}

static void onoff_api_test_init(void)
{
    int rc;
    rc = onoff_manager_init(&mgr, &dummy_client);
    zassert_equal(rc, 0, "Failed to initialize onoff manager");
    atomic_set(&current_state, ONOFF_STATE_OFF);
}

static void *onoff_api_setup(void)
{
    onoff_api_test_init();
    return NULL;
}

ZTEST_SUITE(onoff_api, NULL, onoff_api_setup, NULL, NULL, NULL);

ZTEST_UNIT_TEST(onoff_api, test_basic_async);
ZTEST_UNIT_TEST(onoff_api, test_basic_reset);
